module EG_PHY_LSLICE
  (
  a,
  b,
  c,
  ce,
  clk,
  d,
  e,
  mi,
  sr,
  fci,
  f,
  fx,
  q,
  fco,
  dpram_mode,
  dpram_di,
  dpram_we,
  dpram_waddr,
  dpram_wclk    
  );
  input [1:0] a;   	//  [Template:Input combinatorial logic data.]
  input [1:0] b;      //  [Template:Input combinatorial logic data.]
  input [1:0] c;      //  [Template:Input combinatorial logic data.]
  input [1:0] d;      //  [Template:Input combinatorial logic data.]
  input [1:0] e;      //  [Template:Input combinatorial logic data.]
  input	[1:0] mi;     //  [Template:Input register data.]
  input clk;                   //  [Template:Clock input.]
  input ce;                    //  [Template:Clock enable input.]
  input sr;                    //  [Template:DFF reset contrl.]
  input fci;                   //  [Template:carry input.]
  output [1:0] f;      //  [Template:LUT primary output.]
  output [1:0] fx;     //  [Template:LUT auxiliary output.]
  output [1:0] q;      //  [Template:Lslice output.] 
  output fco;                  //  [Template:carry output.]
                            
  output [3:0] dpram_di;       //  [Template:Disram writes data output.]
  output [3:0] dpram_waddr;    //  [Template:Disram writes address output.]
  output dpram_wclk;           //  [Template:Disram writes clock output.]
  output dpram_we;             //  [Template:Disram writes enable output.]
  output dpram_mode;           //  [Template:Disram mode contrl output.]

wire [1:0] q_tmp;
buf (q[0],q_tmp[0]);
buf (q[1],q_tmp[1]);
    
tri1 [1:0] a,b,c,d,e,mi;
tri1 clk;
tri1 ce;
tri1 sr;
tri0 fci;  

